const toolsData={pdf:[{title:"Merge PDF",icon:"🔗",url:"merge-pdf.html"},{title:"Split PDF",icon:"✂️",url:"split-pdf.html"},{title:"JPEG to PDF",icon:"🖼️",url:"jpeg-to-pdf.html"},{title:"Reorder PDF Pages",icon:"🗂️",url:"organize-pdf.html"},{title:"Rotate PDF",icon:"🔄",url:"rotate-pdf.html"},{title:"Add Watermark",icon:"💧",url:"add-watermark.html"},{title:"Protect PDF",icon:"🔒",url:"protect-pdf.html"},{title:"Unlock PDF",icon:"🔓",url:"unlock-pdf.html"},{title:"Compress PDF",icon:"🗜️",url:"compress-pdf.html",badge:"API"},{title:"PDF to Word",icon:"📄",url:"pdf-to-word.html",badge:"API"},{title:"Word to PDF",icon:"📝",url:"word-to-pdf.html",badge:"API"},{title:"PDF to JPG",icon:"📷",url:"pdf-to-jpg.html",badge:"API"},{title:"Edit PDF",icon:"✏️",url:"edit-pdf.html"}],utility:[{title:"Image Compressor",icon:"💨",url:"image-compressor.html"},{title:"Image Converter",icon:"🔄",url:"image-converter.html"},{title:"QR Code Generator",icon:"📱",url:"qr-code-generator.html"},{title:"Password Generator",icon:"🔑",url:"password-generator.html"},{title:"Word Counter",icon:"🧮",url:"word-counter.html"},{title:"Text to Speech",icon:"🗣️",url:"text-to-speech.html"},{title:"Speech to Text",icon:"🎤",url:"speech-to-text.html"},{title:"JSON Formatter",icon:"{ }",url:"json-formatter.html"},{title:"Case Converter",icon:"Aa",url:"case-converter.html"},{title:"Lorem Ipsum Generator",icon:"¶",url:"lorem-ipsum-generator.html"},{title:"Base64 Encoder/Decoder",icon:"🔐",url:"base64-encoderdecoder.html"},{title:"Age Calculator",icon:"🎂",url:"age-calculator.html"},{title:"BMI Calculator",icon:"💪",url:"bmi-calculator.html"},{title:"Color Picker",icon:"🎨",url:"color-picker.html"},{title:"Unit Converter",icon:"📏",url:"unit-converter.html"},{title:"Image OCR",icon:"🔍",url:"image-ocr.html",badge:"API"}]};class ToolNavigator{constructor(){this.isOpen=!1,this.currentTool=this.getCurrentToolName(),this.init()}getCurrentToolName(){return window.location.pathname.split("/").pop()||""}init(){this.injectHTML(),this.attachEventListeners(),this.highlightCurrentTool()}injectHTML(){const t=`\n            \x3c!-- Tool Navigator Overlay --\x3e\n            <div class="tool-nav-overlay" id="toolNavOverlay"></div>\n            \n            \x3c!-- Tool Navigator Trigger Button --\x3e\n            <button class="tool-navigator-trigger" id="toolNavTrigger" aria-label="Open Tools Menu" title="Browse All Tools">\n                🔧\n                <span class="tool-navigator-tooltip" id="toolNavTooltip">Browse Other<br>Tools</span>\n            </button>\n            \n            \x3c!-- Tool Navigator Panel --\x3e\n            <div class="tool-navigator-panel" id="toolNavPanel">\n                <div class="tool-nav-header">\n                    <div class="tool-nav-title">\n                         All Tools\n                    </div>\n                    <button class="tool-nav-close" id="toolNavClose" aria-label="Close">✕</button>\n                </div>\n                \n                <div class="tool-nav-search">\n                    <input type="text" id="toolNavSearch" placeholder="🔍 Search tools..." />\n                </div>\n                \n                <div class="tool-nav-content" id="toolNavContent">\n                    ${this.renderToolCategories()}\n                </div>\n                \n                <div class="tool-nav-quick">\n                    <div class="tool-nav-quick-title">Quick Access</div>\n                    <div class="tool-nav-quick-btns">\n                        <a href="/" class="tool-nav-quick-btn">🏠 Home</a>\n                        <a href="../about" class="tool-nav-quick-btn">ℹ️ About</a>\n                        <a href="../contact" class="tool-nav-quick-btn">📧 Contact</a>\n                    </div>\n                </div>\n            </div>\n        `;document.body.insertAdjacentHTML("beforeend",t)}renderToolCategories(){let t="";return t+=`\n            <div class="tool-nav-category">\n                <div class="tool-nav-category-title">📄 PDF Tools (${toolsData.pdf.length})</div>\n                <div class="tool-nav-list">\n                    ${toolsData.pdf.map(t=>this.renderToolItem(t)).join("")}\n                </div>\n            </div>\n        `,t+=`\n            <div class="tool-nav-category">\n                <div class="tool-nav-category-title">🔧 Utility Tools (${toolsData.utility.length})</div>\n                <div class="tool-nav-list">\n                    ${toolsData.utility.map(t=>this.renderToolItem(t)).join("")}\n                </div>\n            </div>\n        `,t}renderToolItem(t){const o=this.currentTool===t.url?"active":"",e=t.badge?`<span class="tool-nav-badge">${t.badge}</span>`:"";return`\n            <a href="${t.url}" class="tool-nav-item ${o}" data-tool="${t.title}">\n                <span class="tool-nav-icon">${t.icon}</span>\n                <span class="tool-nav-text">${t.title}</span>\n                ${e}\n            </a>\n        `}attachEventListeners(){const t=document.getElementById("toolNavTrigger"),o=(document.getElementById("toolNavPanel"),document.getElementById("toolNavOverlay")),e=document.getElementById("toolNavClose"),l=document.getElementById("toolNavSearch");t.addEventListener("click",()=>this.toggle()),e.addEventListener("click",()=>this.close()),o.addEventListener("click",()=>this.close()),l.addEventListener("input",t=>this.filterTools(t.target.value)),document.addEventListener("keydown",t=>{"Escape"===t.key&&this.isOpen&&this.close()});document.querySelectorAll(".tool-nav-item").forEach(t=>{t.addEventListener("click",()=>{const o=t.dataset.tool;console.log(`Navigating to: ${o}`)})})}toggle(){if(this.isOpen)this.close();else{this.open();const t=document.getElementById("toolNavTooltip");t&&t.classList.add("hidden")}}open(){const t=document.getElementById("toolNavPanel"),o=document.getElementById("toolNavOverlay");t.classList.add("open"),o.classList.add("show"),this.isOpen=!0,document.body.style.overflow="hidden"}close(){const t=document.getElementById("toolNavPanel"),o=document.getElementById("toolNavOverlay");t.classList.remove("open"),o.classList.remove("show"),this.isOpen=!1,document.body.style.overflow=""}filterTools(t){const o=document.querySelectorAll(".tool-nav-item"),e=document.querySelectorAll(".tool-nav-category"),l=t.toLowerCase().trim();if(!l)return o.forEach(t=>t.style.display="flex"),void e.forEach(t=>t.style.display="block");o.forEach(t=>{t.dataset.tool.toLowerCase().includes(l)?t.style.display="flex":t.style.display="none"}),e.forEach(t=>{0===t.querySelectorAll('.tool-nav-item[style*="display: flex"]').length?t.style.display="none":t.style.display="block"})}highlightCurrentTool(){document.querySelectorAll(".tool-nav-item").forEach(t=>{t.getAttribute("href")===this.currentTool&&t.classList.add("active")})}}document.addEventListener("DOMContentLoaded",()=>{if(window.location.pathname.includes("/tools/")){new ToolNavigator;console.log("🔧 Tool Navigator initialized")}});